(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const CATS={food:['☕','Food & chai','#ffb3a7'],delivery:['🛵','Food delivery','#ff9dba'],transport:['🚇','Transport','#bdb5ff'],shopping:['🛍️','Shopping','#d7b8c7'],fun:['🎬','Fun & outings','#d9ff4f'],health:['🩹','Health & care','#b6efc2'],study:['📚','Study & tools','#9fb4ff'],other:['✳','Other','#d9d0d2'],surprise:['⚡','Unexpected','#ff7448'],bills:['🧾','Bills','#e3cfa8'],subs:['📺','Subscriptions','#bcd9a8'],goal:['🎯','Goals','#ffd0a8'],income:['💸','Money in','#b6efc2']};
const challenges=[{id:'main',emoji:'🧃',name:'Broke But Functional',desc:'Survive 30 days on ₹10,000. Main-character budgeting, no side quests.',days:30,reward:150},{id:'delivery',emoji:'🛵',name:'No Food Delivery',desc:'Give the delivery apps a little situationship break.',days:14,reward:100},{id:'cash',emoji:'💵',name:'Cash Only Week',desc:'Feel every rupee. Log every purchase for seven days.',days:7,reward:80},{id:'wait',emoji:'🛒',name:'Cart? I Don’t Know Her',desc:'Wait 7 days before buying a non-essential wishlist item.',days:7,reward:60},{id:'under',emoji:'🧠',name:'Under Allowance Club',desc:'Close 7 days at or below your daily allowance.',days:7,reward:120},{id:'weekend',emoji:'🪩',name:'No-Spend Weekend',desc:'Two days of spending on needs only.',days:2,reward:60},{id:'purge',emoji:'🧹',name:'Subscription Purge',desc:'Review every subscription. Keep the ones you use; pause the ones you forgot.',days:1,reward:70}];
const defaults=()=>({name:'Demo User',email:'demo@mabel.app',budget:10000,days:30,day:12,tx:[{id:1,day:1,type:'out',amt:40,cat:'food',note:'Morning chai',pay:'upi'},{id:2,day:2,type:'out',amt:290,cat:'delivery',note:'Zomato order',pay:'upi'},{id:3,day:3,type:'out',amt:60,cat:'transport',note:'Metro card',pay:'upi'},{id:4,day:4,type:'out',amt:799,cat:'shopping',note:'Phone case + bits',pay:'upi'},{id:5,day:5,type:'out',amt:120,cat:'food',note:'Lunch',pay:'cash'},{id:6,day:6,type:'out',amt:250,cat:'fun',note:'Movie night',pay:'upi'},{id:7,day:7,type:'out',amt:180,cat:'food',note:'Boba',pay:'upi'},{id:8,day:8,type:'out',amt:350,cat:'bills',note:'Wi-Fi share',pay:'upi'},{id:9,day:9,type:'out',amt:199,cat:'subs',note:'Netflix',pay:'auto'},{id:10,day:10,type:'out',amt:80,cat:'transport',note:'Auto',pay:'upi'},{id:11,day:11,type:'in',amt:1500,cat:'income',note:'Freelance payment',pay:'bank'}],goals:[{id:1,name:'Emergency fund',emoji:'🛟',target:3000,saved:1200},{id:2,name:'Jaipur weekend',emoji:'🚆',target:5000,saved:1800},{id:3,name:'New headphones',emoji:'🎧',target:2500,saved:500}],subs:[{id:1,name:'Spotify',emoji:'🎵',amt:119,due:14,active:true},{id:2,name:'Netflix',emoji:'📺',amt:199,due:16,active:true},{id:3,name:'YouTube Premium',emoji:'▶️',amt:129,due:5,active:true}],bills:[{id:4,name:'Phone recharge',emoji:'📱',amt:299,due:8,active:true},{id:5,name:'Mess / tiffin',emoji:'🍱',amt:1200,due:15,active:true}],wishlist:[{id:1,name:'New sneakers',amt:2499,age:3}],board:[{id:1,text:'Small choices today, a freer tomorrow. ♡',kind:'note'},{id:2,text:'JAIPUR WEEKEND',kind:'goal'}],activeChallenges:['main'],doneChallenges:[],challengeProgress:{},scratchDate:null,scratchReward:0,aura:280,streak:3,mode:'aesthetic',theme:'light',quiet:false,chaos:true});
let state=null,authMode='login',currentPage='home',toastTimer=null;if(!localStorage.getItem('mabel-preferred-mode'))localStorage.setItem('mabel-preferred-mode','aesthetic');document.documentElement.dataset.mode=localStorage.getItem('mabel-preferred-mode');
const money=n=>'₹'+Math.round(n||0).toLocaleString('en-IN'),sum=a=>a.reduce((s,x)=>s+x,0),spent=()=>sum(state.tx.filter(t=>t.type==='out').map(t=>t.amt)),income=()=>sum(state.tx.filter(t=>t.type==='in').map(t=>t.amt)),balance=()=>state.budget+income()-spent(),daysLeft=()=>Math.max(0,state.days-state.day+1),spentDay=d=>sum(state.tx.filter(t=>t.type==='out'&&t.day===d).map(t=>t.amt)),daily=()=>Math.max(0,(balance()-state.subs.filter(s=>s.active&&s.due>state.day).reduce((s,x)=>s+x.amt,0)-state.bills.filter(s=>s.active&&s.due>state.day).reduce((s,x)=>s+x.amt,0))/Math.max(1,daysLeft()));
function persist(){if(state){localStorage.setItem('mabel-state-'+state.email,JSON.stringify(state));localStorage.setItem('mabel-session',state.email)}}
function loadSaved(email){try{return JSON.parse(localStorage.getItem('mabel-state-'+email))}catch{return null}}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function authView(mode){authMode=mode;$('#auth-title').textContent=mode==='signup'?'Make it official.':'Welcome back.';$('#auth-sub').textContent=mode==='signup'?'New account, new money lore.':'Your future self saved you a seat.';$('#name-field').classList.toggle('hidden',mode!=='signup');$('#auth-password').autocomplete=mode==='signup'?'new-password':'current-password';$('#auth-submit').innerHTML=(mode==='signup'?'Create account':'Log in')+' <span>↗</span>';$('#switch-copy').textContent=mode==='signup'?'Already one of us?':'New around here?';$('#auth-switch').textContent=mode==='signup'?'Log in':'Create an account';$('#auth-error').textContent='';let pref=localStorage.getItem('mabel-preferred-mode')||'aesthetic';$$('[data-act=choose-vibe]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===pref));document.documentElement.dataset.mode=pref}
$('#auth-switch').onclick=()=>authView(authMode==='signup'?'login':'signup');
$('#auth-form').addEventListener('submit',e=>{e.preventDefault();let email=$('#auth-email').value.trim().toLowerCase(),pw=$('#auth-password').value; if(authMode==='signup'){let name=$('#auth-name').value.trim();if(name.length<2){$('#auth-error').textContent='Give us a name with at least 2 characters.';return}if(pw.length<6){$('#auth-error').textContent='Use at least 6 characters for this prototype.';return}if(loadSaved(email)||localStorage.getItem('mabel-user-'+email)){$('#auth-error').textContent='Account exists here already. Log in instead.';return}state=defaults();state.mode=localStorage.getItem('mabel-preferred-mode')||'aesthetic';state.name=name;state.email=email;localStorage.setItem('mabel-user-'+email,JSON.stringify({name,email,pw}));persist();startApp()}else{let u;try{u=JSON.parse(localStorage.getItem('mabel-user-'+email))}catch{}if(!u||u.pw!==pw){$('#auth-error').textContent='No matching local account. Try the demo or create an account.';return}state=loadSaved(email)||defaults();state.name=u.name;state.email=email;persist();startApp()}});
$('#demo-login').onclick=()=>{let email='demo@mabel.app';state=loadSaved(email)||defaults();state.mode=localStorage.getItem('mabel-preferred-mode')||state.mode||'aesthetic';state.email=email;state.name='Demo User';persist();startApp()};
function startApp(){if(!state) return;state.board=state.board||[];state.wishlist=state.wishlist||[];state.challengeProgress=state.challengeProgress||{};state.doneChallenges=state.doneChallenges||[];if(!state.mode)state.mode='aesthetic';$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');$('#side-name').textContent=state.name;$('#side-avatar').textContent=(state.name[0]||'M').toUpperCase();$('#profile-btn').textContent=(state.name[0]||'M').toUpperCase();document.documentElement.dataset.theme=state.theme||'light';document.documentElement.dataset.mode=state.mode||'aesthetic';$('#vibe-toggle').innerHTML=(state.mode==='chill'?'😎 <span>Vibe: Chill</span>':'✿ <span>Vibe: Aesthetic</span>');$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===currentPage));render();persist()}
function logout(){persist();state=null;$('#app').classList.add('hidden');$('#auth').classList.remove('hidden');$('#auth-email').value='';$('#auth-password').value='';authView('login')}
$('#logout').onclick=logout;$('#profile-btn').onclick=()=>go('settings');$('#theme-toggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;persist();toast(state.theme==='dark'?'Dark mode: activated. 🖤':'Back to daylight. ☀️')};
$('#vibe-toggle').onclick=()=>{state.mode=state.mode==='chill'?'aesthetic':'chill';document.documentElement.dataset.mode=state.mode;$('#vibe-toggle').innerHTML=(state.mode==='chill'?'😎 <span>Vibe: Chill</span>':'✿ <span>Vibe: Aesthetic</span>');persist();toast(state.mode==='chill'?'Unhinged honesty: ON.':'Soft reset mode: ON.');render()};
$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');
function go(page){currentPage=page;$('#sidebar').classList.remove('open');$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));render();window.scrollTo({top:0,behavior:'smooth'})}
$('#nav-list').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});
function head(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function btn(label,act,cls='outline',extra=''){return `<button class="btn ${cls}" data-act="${act}" ${extra}>${label}</button>`}
function stat(label,value,foot){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function panel(title,body,extra=''){return `<section class="panel ${extra}"><div class="panel-head"><h3>${title}</h3></div>${body}</section>`}
function txRow(t){let c=CATS[t.cat]||CATS.other;return `<div class="tx-row"><div class="tx-icon" style="background:${c[2]}">${c[0]}</div><div class="tx-info"><b>${esc(t.note||c[1])}</b><small>Day ${t.day} · ${c[1]} · ${t.pay||'UPI'}</small></div><div class="tx-amt ${t.type==='in'?'income':''}">${t.type==='in'?'+':'−'}${money(t.amt)}<button data-act="delete-tx" data-id="${t.id}">remove</button></div></div>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function txList(items){return `<div class="tx-list">${items.length?items.slice().reverse().map(txRow).join(''):'<div class="empty">No money lore yet. Log your first transaction ✳</div>'}</div>`}
function bars(){let vals=Array.from({length:7},(_,i)=>spentDay(Math.max(1,state.day-6+i))),max=Math.max(100,...vals);return `<div class="bars">${vals.map((v,i)=>`<div class="bar-col"><span class="bar-num">${v?money(v):'—'}</span><div class="bar ${i===6?'hot':''}" style="height:${Math.max(3,v/max*110)}px" title="${money(v)}"></div><span class="bar-label">D${Math.max(1,state.day-6+i)}</span></div>`).join('')}</div>`}
function categoryBreakdown(){let vals=Object.keys(CATS).map(k=>({k,v:sum(state.tx.filter(t=>t.type==='out'&&t.cat===k).map(t=>t.amt))})).filter(x=>x.v).sort((a,b)=>b.v-a.v);let max=Math.max(1,...vals.map(x=>x.v));return vals.length?vals.slice(0,7).map(x=>`<div class="category-row"><span>${CATS[x.k][0]}</span><span>${CATS[x.k][1]}</span><div class="progress"><i style="width:${x.v/max*100}%;background:${CATS[x.k][2]}"></i></div><strong>${money(x.v)}</strong></div>`).join(''):'<div class="empty">Your categories will show up here.</div>'}
function quick(){return `<div class="grid quick-grid"><button class="quick" data-act="open-tx"><span class="qicon">↗</span>Log expense</button><button class="quick" data-act="open-income"><span class="qicon">＋</span>Money in</button><button class="quick" data-act="page-sim"><span class="qicon">⌁</span>Run a what-if</button><button class="quick" data-act="page-goals"><span class="qicon">◎</span>Fund a goal</button></div>`}
function home(){let bal=balance(),risk=riskScore(),allow=daily(),progress=(state.day/state.days)*100;return `${head('MONDAY ENERGY, EVERY DAY','Hey, '+esc(state.name.split(' ')[0])+'. ✳','The goal isn’t perfect money. It’s fewer “where did it go?” moments.',btn('＋ Log money','open-tx','primary'))}<div class="grid stats-grid">${stat('Money left',money(bal),`${money(state.budget)} starting budget`)}${stat('Daily allowance',money(allow),'Safe-to-spend estimate')}${stat('Already spent',money(spent()),`${Math.round(spent()/Math.max(1,state.budget)*100)}% of starting budget`)}${stat('Your aura',state.aura+' ✦',`${state.streak}-day streak · keep cooking`)}</div><div class="grid two-col"><div class="grid"><section class="panel hero-panel"><div class="section-label">THE 30-DAY MAIN QUEST · DAY ${state.day}/${state.days}</div><h2>${bal>=0?'Not broke. Just getting intentional.':'Plot twist: time for a rescue plan.'}</h2><p>${bal>=0?'You’ve got '+money(bal)+' in the tank. Make the next choice count.':'You’re '+money(Math.abs(bal))+' over budget. Let’s inspect the next few decisions and find some breathing room.'}</p><div class="progress acid"><i style="width:${progress}%"></i></div><div class="budget-row"><span>DAY ${state.day} OF ${state.days}</span><span>${Math.round(progress)}% of the plot</span></div>${btn('Open the what-if lab ↗','page-sim','primary')}</section><div class="grid two-col"><section class="panel"><div class="panel-head"><h3>Spending lately</h3><span class="pill">7 DAYS</span></div>${bars()}</section><section class="panel"><div class="panel-head"><h3>Money breakdown</h3><span class="pill">ALL TIME</span></div>${categoryBreakdown()}</section></div>${panel('Recent money moves',txList(state.tx.slice(-5)), '')}</div><div class="grid"><section class="panel"><div class="panel-head"><h3>Today’s control centre</h3><span class="pill green">YOU GOT THIS</span></div>${quick()}<div class="notice" style="margin-top:16px">✳ <b>Friendly reminder:</b> the daily allowance is a guide based on your current balance and days left, not a rule you have to feel guilty about.</div></section><section class="panel"><div class="panel-head"><h3>Current side quests</h3>${btn('All challenges ↗','page-challenges','outline')}</div>${state.activeChallenges.map(id=>challenges.find(c=>c.id===id)).filter(Boolean).map(c=>`<div class="commit-row"><div class="ci">${c.emoji}</div><div class="grow"><b>${c.name}</b><small>${c.days}-day challenge · ${c.reward} aura on completion</small></div><span class="pill">${Math.min(state.day,c.days)}/${c.days} days</span></div>`).join('')||'<div class="empty">No active side quests. Choose one to begin.</div>'}</section><div class="meme-card"><div class="eyebrow">MABEL HAS ENTERED THE CHAT</div><div class="meme">${state.mode==='chill'?'“I can afford it” is not the same as “it fits the plan.”':'Small choices today. A freer tomorrow. ✳'}</div><p>Zero judgement. Just maths with personality.</p></div></div></div>`}
function tracker(){let q=new URLSearchParams(location.hash.split('?')[1]||'').get('q')||'';return `${head('RECEIPTS, BUT MAKE IT USEFUL','Track the plot.','Every transaction updates your balance, daily allowance and forecast.',btn('＋ Add transaction','open-tx','primary'))}<div class="grid stats-grid">${stat('Money out',money(spent()),'All logged expenses')}${stat('Money in',money(income()),'Income recorded')}${stat('Net change',money(income()-spent()),'Income minus spending')}${stat('Transactions',state.tx.length,'Every entry counts')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><h3>All transactions</h3><span class="pill">${state.tx.length} ENTRIES</span></div><div class="form-field" style="margin-bottom:12px"><input id="tx-search" type="search" placeholder="Search chai, metro, shopping…" value="${esc(q)}"></div><div id="tx-results">${txList(state.tx.filter(t=>!q||(t.note+' '+(CATS[t.cat]||['',''])[1]).toLowerCase().includes(q.toLowerCase())))}</div></section><div class="grid">${panel('Category breakdown',categoryBreakdown())}<section class="panel"><div class="panel-head"><h3>Logging rules</h3><span class="pill pink">NO SHAME</span></div><p class="muted" style="font-size:12px;line-height:1.8">Log expenses when they happen. Add income when it lands. Use “unexpected” for real surprises—not for every little treat. You can remove an entry if you made a mistake.</p>${btn('Log a quick chai ☕','quick-chai','outline')}</section></div></div>`}
function riskScore(){let d=Math.max(1,daysLeft()),allow=daily(),pace=spent()/Math.max(1,state.day);let ratio=pace/(Math.max(1,(state.budget+income())/state.days));return Math.max(0,Math.min(100,Math.round((balance()<0?80:ratio*48)+(state.subs.reduce((a,s)=>a+(s.active?s.amt:0),0)/Math.max(1,state.budget)*20))))}
function runMonteCarlo(purchase,shock){let futureDays=Math.max(0,state.days-state.day),hist=[];for(let d=1;d<state.day;d++)hist.push(spentDay(d));let mean=hist.length?sum(hist)/hist.length:Math.max(0,daily()),variance=hist.length?sum(hist.map(v=>(v-mean)*(v-mean)))/hist.length:Math.pow(mean*.35,2),sd=Math.sqrt(variance)||Math.max(30,mean*.3),upcoming=[...state.subs,...state.bills].filter(x=>x.active&&x.due>state.day&&x.due<=state.days).reduce((a,x)=>a+x.amt,0),start=balance()-Math.max(0,purchase||0)-Math.max(0,shock||0),ends=[];for(let r=0;r<300;r++){let end=start-upcoming;for(let d=0;d<futureDays;d++){let u=Math.max(.0001,Math.random()),v=Math.random(),z=Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v),spend=Math.max(0,Math.min(mean+2.2*sd,mean+z*sd));end-=spend;if(state.chaos&&Math.random()<.075)end-=(300+Math.random()*1500)}ends.push(Math.round(end))}ends.sort((a,b)=>a-b);let q=p=>ends[Math.max(0,Math.min(ends.length-1,Math.floor((ends.length-1)*p)))];return {low:q(.1),mid:q(.5),high:q(.9),survival:Math.round(ends.filter(x=>x>=0).length/Math.max(1,ends.length)*100),runs:ends.length,upcoming,mean,sd}}
function simulate(){let amt=Number($('#sim-amt')?.value||1299),kind=$('#sim-kind')?.value||'want',shock=Number($('#sim-shock')?.value||0),future=balance()-amt-shock,projected=future-Math.max(0,daily())*Math.max(0,daysLeft()-1);let baseline=balance()-Math.max(0,daily())*Math.max(0,daysLeft()-1),mc=runMonteCarlo(amt,shock);let verdict=kind==='need'?'If it’s genuinely essential, make space for it and adjust the rest.':future<0?'Hard pass for now. The maths says this pushes you below zero.':projected<0?'Maybe wait. This purchase makes your month fragile.':'Looks doable, if you still want it after a 24-hour pause.';return `${head('DECISIONS, NOT GUESSES','The what-if lab. 🧪','Try a choice before your bank balance has to experience it.') }<div class="grid two-col"><section class="panel"><div class="panel-head"><h3>Run a scenario</h3><span class="pill pink">LIVE SIMULATION</span></div><div class="form-grid"><div class="form-field full-span"><label>What are we thinking about?</label><input id="sim-name" value="Those headphones 👀" maxlength="70"></div><div class="form-field"><label>Price (₹)</label><input id="sim-amt" type="number" min="0" max="1000000" value="1299"></div><div class="form-field"><label>Purchase type</label><select id="sim-kind"><option value="want">Want</option><option value="need">Need</option></select></div><div class="form-field full-span"><div class="range-line"><label>Unexpected expense added</label><strong id="shock-val">${money(shock)}</strong></div><input class="range" id="sim-shock" type="range" min="0" max="5000" step="100" value="0"></div></div><div class="notice" style="margin:14px 0">This is a planning estimate based on your current entries and remaining days. It is not a prediction of the future.</div><button class="btn primary full" data-act="run-sim">Calculate my consequences ↗</button></section><div class="grid"><section class="panel"><div class="panel-head"><h3>After this purchase</h3><span class="pill">SCENARIO</span></div><div class="stat-label">Estimated balance right after</div><div class="stat-value" id="sim-balance">${money(balance()-1299)}</div><div class="budget-row"><span>Current balance</span><b>${money(balance())}</b></div><div class="budget-row"><span>Purchase</span><b>−${money(1299)}</b></div><div class="budget-row"><span>Unexpected expense</span><b>−${money(shock)}</b></div><div class="progress" style="margin:15px 0"><i id="sim-progress" style="width:${Math.max(0,Math.min(100,(balance()-1299)/Math.max(1,state.budget)*100))}%"></i></div><div id="sim-verdict" class="decision"><div class="eyebrow">MABEL’S TAKE</div><h3>${verdict}</h3><p>Current plan baseline: ${money(baseline)} projected at the end of the month before this purchase.</p></div></section><section class="panel"><div class="panel-head"><h3>Stress-test your month</h3><span class="pill">QUICK SHOCKS</span></div>${[['📱','Phone screen repair',1800],['🎁','Friend’s birthday',700],['🖨️','Prints + lab fee',600],['🛺','Missed the last bus',450]].map(x=>`<div class="scenario-card"><b>${x[0]} ${x[1]}</b><p>A very believable plot twist.</p><button class="choice" data-act="apply-shock" data-amt="${x[2]}">Add ${money(x[2])} to scenario</button></div>`).join('')}</section><section class="panel monte-panel"><div class="panel-head"><h3>300 possible versions of your month</h3><span class="pill pink">MONTE CARLO</span></div><p class="muted">A range of possible outcomes using your logged spending pace, upcoming commitments and optional surprise costs. Not a guarantee.</p><div class="monte-survival"><b id="mc-survival">${mc.survival}%</b><span>simulated paths finish above ₹0</span></div><div class="monte-range"><div><small>Rough month</small><b id="mc-low">${money(mc.low)}</b></div><div><small>Middle outcome</small><b id="mc-mid">${money(mc.mid)}</b></div><div><small>Good month</small><b id="mc-high">${money(mc.high)}</b></div></div><div class="monte-track"><i style="left:10%"></i><i style="left:50%"></i><i style="left:90%"></i></div><button class="btn outline" data-act="rerun-monte">Run 300 paths again ↻</button><p class="tiny muted" style="margin-top:10px">The simulation uses a simplified distribution; actual spending can differ substantially.</p></section></div></div>`}
function plan(){let up=state.subs.filter(s=>s.active).reduce((a,s)=>a+s.amt,0)+state.bills.filter(s=>s.active).reduce((a,s)=>a+s.amt,0);return `${head('A PLAN, NOT A PRISON','Give your month a plot.','Set your starting budget, timeline and daily pace. Changes recalculate the whole picture.',btn('Save plan','save-plan','primary'))}<div class="grid two-col"><section class="panel"><div class="panel-head"><h3>Your month settings</h3><span class="pill green">EDITABLE</span></div><div class="form-grid"><div class="form-field"><label>Starting budget (₹)</label><input id="plan-budget" type="number" min="1" max="10000000" value="${state.budget}"></div><div class="form-field"><label>Days in your challenge</label><select id="plan-days">${[7,14,21,30,31].map(n=>`<option ${state.days===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="form-field"><label>Current day</label><input id="plan-day" type="number" min="1" max="${state.days}" value="${state.day}"></div></div><div class="notice" style="margin:16px 0">Tip: set your actual spendable amount after money you cannot use. Fixed bills and subscriptions are shown separately below.</div>${btn('Recalculate my month ↗','save-plan','primary')}</section><div class="grid">${panel('Your plan at a glance',`<div class="budget-row"><span>Starting budget</span><b>${money(state.budget)}</b></div><div class="budget-row"><span>Income recorded</span><b>${money(income())}</b></div><div class="budget-row"><span>Spent so far</span><b>${money(spent())}</b></div><div class="budget-row"><span>Fixed costs tracked</span><b>${money(up)}</b></div><div class="budget-row"><span>Balance after logged transactions</span><b>${money(balance())}</b></div><div class="budget-row"><span>Daily guide from today</span><b>${money(daily())}</b></div>`)}<section class="panel"><div class="panel-head"><h3>Daily allowance ≠ daily target</h3></div><p class="muted" style="font-size:12px;line-height:1.8">A daily allowance is a flexible guide based on money remaining and time left. Spend less on an easy day, spend more on a necessary one. The point is to notice trade-offs before they surprise you.</p></section></div></div>`}
function goals(){return `${head('FUTURE YOU SAYS THANKS','Goals with main-character energy.','Give your money a job before it disappears into little treats.',btn('＋ New goal','new-goal','primary'))}<div class="grid three-col">${state.goals.map(g=>`<section class="goal-card"><div class="goal-top"><div class="goal-emoji">${g.emoji||'◎'}</div><div><h3>${esc(g.name)}</h3><p>${Math.round(g.saved/Math.max(1,g.target)*100)}% funded</p></div></div><div class="goal-money"><span>${money(g.saved)} saved</span><span>of ${money(g.target)}</span></div><div class="progress"><i style="width:${Math.min(100,g.saved/Math.max(1,g.target)*100)}%"></i></div><button class="btn outline" data-act="fund-goal" data-id="${g.id}">＋ Add money</button></section>`).join('')}</div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Make saving feel less abstract</h3><span class="pill pink">TINY WINS</span></div><div class="grid three-col"><div class="scenario-card"><b>🛟 Emergency fund</b><p>Protect your future self from plot twists.</p></div><div class="scenario-card"><b>🚆 A trip worth remembering</b><p>Save towards the thing, not just away from spending.</p></div><div class="scenario-card"><b>🎧 The thing you actually want</b><p>Wishlist it, plan it, buy it without the guilt spiral.</p></div></div></section>`}
function commitments(){let all=[...state.bills.map(x=>({...x,type:'Bill'})),...state.subs.map(x=>({...x,type:'Subscription'}))];return `${head('THE RECURRING STUFF','Bills, subs & sneaky little charges.','Keep commitments visible before they quietly eat the budget.',btn('＋ Add commitment','new-commit','primary'))}<div class="grid stats-grid">${stat('Monthly commitments',money(all.filter(x=>x.active).reduce((a,x)=>a+x.amt,0)),'Active recurring costs')}${stat('Subscriptions',state.subs.filter(x=>x.active).length,'Streaming, apps and more')}${stat('Bills',state.bills.filter(x=>x.active).length,'Essential-ish costs')}${stat('Next due',all.filter(x=>x.active&&x.due>=state.day).sort((a,b)=>a.due-b.due)[0]?`Day ${all.filter(x=>x.active&&x.due>=state.day).sort((a,b)=>a.due-b.due)[0].due}`:'—','Upcoming in your plan')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><h3>Subscriptions</h3><span class="pill">${state.subs.filter(s=>s.active).length} ACTIVE</span></div>${state.subs.map(x=>commitRow(x,'sub')).join('')||'<div class="empty">No subscriptions yet.</div>'}</section><section class="panel"><div class="panel-head"><h3>Bills & essentials</h3><span class="pill">${state.bills.filter(s=>s.active).length} ACTIVE</span></div>${state.bills.map(x=>commitRow(x,'bill')).join('')||'<div class="empty">No bills yet.</div>'}<div class="notice">These are tracked commitments. They are not automatically deducted from your logged balance in this prototype unless you log the payment as a transaction.</div></section></div>`}
function commitRow(x,type){return `<div class="commit-row"><div class="ci">${x.emoji||'🧾'}</div><div class="grow"><b>${esc(x.name)}</b><small>${type==='sub'?'Subscription':'Bill'} · due day ${x.due} · ${x.active?'active':'paused'}${type==='sub'?(x.reviewed?' · reviewed':' · not reviewed'):''}</small></div><strong>${money(x.amt)}</strong>${type==='sub'?`<button class="choice" data-act="review-sub" data-id="${x.id}">${x.reviewed?'Reviewed ✓':'Review'}</button>`:''}<button class="choice" data-act="toggle-commit" data-type="${type}" data-id="${x.id}">${x.active?'Pause':'Resume'}</button></div>`}
function challengesPage(){return `${head('SIDE QUESTS = BETTER HABITS','Make it a little game.','Tiny rules, visible progress, rewards for showing up—not for being perfect.',`<span class="pill green">${state.aura} AURA ✦</span>`)}<div class="grid three-col">${challenges.map(c=>{let active=state.activeChallenges.includes(c.id),done=state.doneChallenges.includes(c.id),prog=c.id==='main'?Math.min(state.day,c.days):(state.challengeProgress[c.id]||0),p=done?100:active?Math.min(100,prog/c.days*100):0;return `<article class="challenge-card"><div class="eyebrow">${done?'QUEST CLEARED':active?'IN PROGRESS':'OPTIONAL SIDE QUEST'}</div><div style="font-size:31px;margin-top:7px">${c.emoji}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="budget-row"><span>${active?prog:0}/${c.days} days</span><b>+${c.reward} aura</b></div><div class="progress"><i style="width:${p}%"></i></div>${done?'<button class="btn" disabled>Completed ✓</button>':active?(c.id==='main'?'<button class="btn" data-act="page-plan">Update month plan ↗</button>':`<button class="btn" data-act="challenge-tick" data-id="${c.id}">Count today’s win ✓</button><button class="btn outline" data-act="leave-challenge" data-id="${c.id}">Pause quest</button>`):`<button class="btn" data-act="join-challenge" data-id="${c.id}">Accept quest ↗</button>`}</article>`}).join('')}</div><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>Your badge shelf</h3><span class="pill pink">${state.doneChallenges.length} UNLOCKED</span></div><div class="badge-grid">${[['✦','First step','Log a transaction'],['🧠','Mindful era','Try the what-if lab'],['🛟','Safety net','Create a goal'],['🪩','Main character','Finish a challenge']].map((b,i)=>`<div class="badge-card"><div class="badge-icon">${state.tx.length&&i===0||state.doneChallenges.length&&i===3||state.goals.length&&i===2?'🏆':b[0]}</div><b>${b[1]}</b><small>${b[2]}</small></div>`).join('')}</div></section>`}
function insights(){let risk=riskScore(),by=Object.keys(CATS).map(k=>({k,v:sum(state.tx.filter(t=>t.type==='out'&&t.cat===k).map(t=>t.amt))})).sort((a,b)=>b.v-a.v),top=by.find(x=>x.v)||{k:'food',v:0};let delivery=state.tx.filter(t=>t.cat==='delivery'&&t.type==='out').reduce((a,t)=>a+t.amt,0);return `${head('THE RECEIPTS HAVE LORE','Money lore. 📈','Patterns, forecasts and financial health—with no spreadsheet jump-scare.')}<div class="grid stats-grid">${stat('Risk indicator',risk+'/100',risk>65?'Tight month — review your plan':'A rough guide, not a verdict')}${stat('Average daily spend',money(spent()/Math.max(1,state.day)),'Based on logged transactions')}${stat('Projected month-end',money(balance()-spent()/Math.max(1,state.day)*daysLeft()),'Simple pace-based estimate')}${stat('Top category',CATS[top.k][1],money(top.v)+' logged')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><h3>Spending over the last 7 days</h3><span class="pill">TREND</span></div>${bars()}<p class="muted tiny" style="margin-top:12px">Daily totals are based only on transactions you log. Missing entries can make this chart incomplete.</p></section><section class="panel"><div class="panel-head"><h3>Where the money goes</h3><span class="pill">CATEGORIES</span></div>${categoryBreakdown()}</section></div><div class="grid two-col" style="margin-top:16px"><section class="panel"><div class="panel-head"><h3>Patterns worth noticing</h3><span class="pill pink">NO SHAME</span></div><div class="insight-item"><div class="insight-ico">👀</div><div><b>${CATS[top.k][1]} is your top logged category</b><p>${money(top.v)} so far. This isn't automatically bad—compare it with what matters to you and whether it fits the month.</p></div></div><div class="insight-item"><div class="insight-ico">🛵</div><div><b>Delivery check-in</b><p>${money(delivery)} logged on delivery. If you want to cut back, choose a realistic limit instead of banning everything fun.</p></div></div><div class="insight-item"><div class="insight-ico">🛟</div><div><b>Buffer check</b><p>${balance()>0?'You currently have a positive logged balance. Keep upcoming commitments in view.':'Your logged balance is below zero. Revisit flexible spending and expected income first.'}</p></div></div></section><section class="panel"><div class="panel-head"><h3>Risk ≠ your worth</h3><span class="pill">INDICATIVE</span></div><div class="risk-meter"><div class="risk-score">${risk}</div><div class="risk-track"><i style="width:${risk}%"></i></div></div><p class="muted" style="font-size:12px;line-height:1.8;margin-top:14px">This prototype indicator blends current spending pace and commitments. It is not a bank score, credit score, or professional financial assessment.</p>${btn('Stress-test in the lab ↗','page-sim','primary')}</section></div>`}
function decide(){let n=state.wishlist.length;return `${head('PAUSE BEFORE THE PURCHASE','Should I buy this? ♡','Tell Mabel what is in your cart. We will check the numbers, not judge your taste.')}
<div class="grid two-col"><section class="panel"><div class="panel-head"><h3>The cart interrogation</h3><span class="pill pink">NO SHAME ZONE</span></div><div class="form-grid"><div class="form-field full-span"><label>What are you eyeing?</label><input id="decide-name" maxlength="70" placeholder="Headphones, that bag, concert tickets…"></div><div class="form-field"><label>Price (₹)</label><input id="decide-amt" type="number" min="0" max="1000000" value="1299"></div><div class="form-field"><label>Is it a need or a want?</label><select id="decide-kind"><option value="want">A want (valid!)</option><option value="need">A need</option></select></div><div class="form-field full-span"><label>How long has it been on your mind?</label><div class="chips"><button class="choice selected" data-act="decide-age" data-age="0">Just saw it</button><button class="choice" data-act="decide-age" data-age="3">A few days</button><button class="choice" data-act="decide-age" data-age="7">A week+</button></div><input type="hidden" id="decide-age-value" value="0"></div></div><div class="modal-actions">${btn('Run the numbers ↗','decide-run','primary')}${btn('Save to wishlist','decide-save','outline')}</div><div class="notice" style="margin-top:14px">A “no” is not the goal. The goal is a choice you can afford and still feel good about tomorrow.</div></section><div class="grid"><section class="panel"><div class="panel-head"><h3>Mabel’s verdict</h3><span class="pill">LIVE MATH</span></div><div id="decide-result" class="decision"><div class="eyebrow">THE CART CAN WAIT 2 SECONDS</div><h3>Let’s see what it does to your month.</h3><p>Enter a price and run the numbers to get a grounded estimate.</p></div><div class="budget-row"><span>Current balance</span><b>${money(balance())}</b></div><div class="budget-row"><span>Daily guide right now</span><b>${money(daily())}</b></div></section><section class="panel"><div class="panel-head"><h3>Your wishlist</h3><span class="pill">${n} SAVED</span></div>${n?state.wishlist.map(w=>`<div class="commit-row"><div class="ci">🛍️</div><div class="grow"><b>${esc(w.name)}</b><small>${money(w.amt)} · ${w.age||0} days on the list</small></div><button class="choice" data-act="decide-buy" data-id="${w.id}">Recheck</button></div>`).join(''):'<div class="empty">Your wishlist is peacefully empty. Add something above.</div>'}</section></div></div>`}
function tea(){let out=state.tx.filter(t=>t.type==='out'),by=Object.keys(CATS).map(k=>({k,v:sum(out.filter(t=>t.cat===k).map(t=>t.amt)),n:out.filter(t=>t.cat===k).length})).filter(x=>x.v).sort((a,b)=>b.v-a.v),top=by[0]||{k:'food',v:0,n:0},delivery=out.filter(t=>t.cat==='delivery').reduce((a,t)=>a+t.amt,0),food=out.filter(t=>t.cat==='food').reduce((a,t)=>a+t.amt,0),big=out.slice().sort((a,b)=>b.amt-a.amt)[0],subs=state.subs.filter(x=>x.active),subTotal=subs.reduce((a,x)=>a+x.amt,0),fixed=state.bills.filter(x=>x.active).reduce((a,x)=>a+x.amt,0),avg=spent()/Math.max(1,state.day),pct=Math.round(top.v/Math.max(1,spent())*100);let lines=[];if(top.v)lines.push(`${CATS[top.k][1]} is your top logged category at ${money(top.v)} (${pct}% of tracked spending). That's a pattern, not a personality flaw.`);if(delivery)lines.push(`Food delivery has taken ${money(delivery)} so far. If you want to save, one planned no-delivery day can be a start—no dramatic vows needed.`);if(subs.length)lines.push(`${subs.length} active subscriptions add up to ${money(subTotal)} per month. Keep the ones you genuinely use; pause the rest.`);if(big)lines.push(`Biggest logged spend: ${big.note||CATS[big.cat]?.[1]||'Purchase'} at ${money(big.amt)}. Worth checking whether it was a one-off or a repeat pattern.`);lines.push(`Your current pace is about ${money(avg)} a day. Your live daily guide is ${money(daily())}.`);if(state.goals.length)lines.push(`You have ${state.goals.length} money goal(s) in progress. Small, regular contributions beat an impossible promise.`);return `${head('CHAI PE CHARCHA ☕','Spill the tea.','The monthly money recap that actually says something. Your spending, your patterns, zero shame.')}
<div class="grid stats-grid">${stat('Tracked spending',money(spent()),'Across '+out.length+' expenses')}${stat('Food + chai',money(food),'The little rituals')}${stat('Delivery lore',money(delivery),'Convenience has a cost')}${stat('Fixed commitments',money(subTotal+fixed),'Active bills + subscriptions')}</div><div class="grid two-col"><section class="panel tea-hero"><div class="section-label">MABEL HAS READ THE RECEIPTS</div><h2>Your month has a plot. Here’s the tea.</h2><p>${state.mode==='chill'?'No cap, this is the spending lore. We are reading the receipts, not dragging you.':'A gentle, clear look at where your money went and what you might want to change.'}</p><div class="tea-lines">${lines.map((x,i)=>`<article class="tea-line"><span class="tea-num">0${i+1}</span><p>${esc(x)}</p></article>`).join('')}</div><div class="meme-card" style="margin-top:18px"><div class="eyebrow">THE MONTHLY VERDICT</div><div class="meme">${state.mode==='chill'?'The budget is budgeting. The plot is plotting. Now we adjust.':'You are learning your patterns. That is progress, not failure. ♡'}</div><p>Based on the transactions you've logged. Missing entries can change the story.</p></div></section><div class="grid">${panel('Where the money went',categoryBreakdown())}<section class="panel"><div class="panel-head"><h3>Fixed-cost reality check</h3><span class="pill">RECURRING</span></div>${[...subs.map(x=>({...x,kind:'Subscription'})),...state.bills.filter(x=>x.active).map(x=>({...x,kind:'Bill'}))].map(x=>`<div class="commit-row"><div class="ci">${x.emoji||'🧾'}</div><div class="grow"><b>${esc(x.name)}</b><small>${x.kind} · due day ${x.due}</small></div><strong>${money(x.amt)}</strong></div>`).join('')||'<div class="empty">No recurring costs yet.</div>'}${btn('Review bills & subscriptions ↗','page-commitments','outline')}</section></div></div>`}
function health(){let risk=riskScore(),bal=balance(),runway=daily()>0?Math.max(0,bal)/daily():99,sub=state.subs.filter(x=>x.active).reduce((a,x)=>a+x.amt,0),bill=state.bills.filter(x=>x.active).reduce((a,x)=>a+x.amt,0),saved=state.goals.reduce((a,g)=>a+g.saved,0),score=Math.max(0,Math.min(100,Math.round(100-risk*.55+(bal<0?-20:bal/state.budget*10)+Math.min(10,saved/Math.max(1,state.budget)*10))));return `${head('CHECK IN, NOT CHECK OUT','Your financial health. ♡','A friendly pulse-check for your month—not a credit score, diagnosis or judgement.')}
<div class="health-score-card"><div><div class="section-label">YOUR MONEY WELLNESS SCORE</div><div class="health-score">${score}<small>/100</small></div><p>${score>=75?'You have some breathing room. Protect it.':score>=50?'There are a few pressure points. You have options.':'This month looks tight. Let’s make a small rescue plan.'}</p></div><div class="health-ring" style="--score:${score}"><span>${score>=75?'✿':score>=50?'♡':'☁'}</span></div></div><div class="grid stats-grid">${stat('Runway',daily()>0?runway.toFixed(1)+' days':'Flexible','At current daily allowance')}${stat('Balance',money(bal),bal>=0?'Still above zero':'Below zero — review plan')}${stat('Savings goals',money(saved),'Across active goals')}${stat('Fixed costs',money(sub+bill),'Monthly commitments tracked')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><h3>What affects your score?</h3><span class="pill">INDICATIVE</span></div>${[['Spending pace',risk>65?'Needs attention':'In a manageable range',risk],['Cash buffer',bal>state.budget*.2?'Some cushion remains':bal>0?'Buffer is getting thin':'No buffer in logged balance',Math.max(0,100-Math.min(100,Math.max(0,1-bal/Math.max(1,state.budget))*100))],['Fixed commitments',money(sub+bill)+' tracked',Math.min(100,(sub+bill)/Math.max(1,state.budget)*100)]].map(x=>`<div class="health-factor"><div class="row"><b>${x[0]}</b><span>${x[1]}</span></div><div class="progress"><i style="width:${Math.max(0,Math.min(100,x[2]))}%"></i></div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h3>Your next gentle moves</h3><span class="pill green">NO SHAME</span></div><div class="insight-item"><div class="insight-ico">🧾</div><div><b>Look at fixed costs</b><p>Review recurring charges before cutting every little joy.</p></div></div><div class="insight-item"><div class="insight-ico">🎯</div><div><b>Protect one small goal</b><p>Even a modest, realistic contribution builds momentum.</p></div></div><div class="insight-item"><div class="insight-ico">🧪</div><div><b>Try a rescue scenario</b><p>Test a purchase or unexpected expense before committing.</p></div></div>${btn('Open what-if lab ↗','page-sim','primary')}</section></div><p class="muted tiny" style="margin-top:14px">This is a simplified educational estimate based on the information entered in Mabel. It is not financial advice.</p>`}
function rewards(){let defs=[['first','First receipt','Log your first transaction',state.tx.length>0,'🧾'],['planner','Plot armour','Set up your month plan',state.budget>0,'🗓️'],['goal','Future-you fan','Create a savings goal',state.goals.length>0,'🎯'],['mindful','Cart investigator','Try the purchase decision tool',!!state.seenDecide,'🛍️'],['tea','Tea spiller','Read your monthly recap',!!state.seenTea,'☕'],['quest','Side-quester','Join a challenge',state.activeChallenges.length>0,'⚔️'],['streak','Consistency core','Build a 3-day streak',state.streak>=3,'🔥'],['saver','Little by little','Save towards a goal',state.goals.some(g=>g.saved>0),'🛟']];let level=state.aura>=1500?'Rich era':state.aura>=700?'Pre-rich arc':state.aura>=300?'Main character':state.aura>=100?'Side character':'NPC';return `${head('TINY WINS, BIG AURA','Your badge shelf. ✦','Progress is not perfection. Every small, thoughtful choice counts.')}
<div class="reward-hero"><div><div class="section-label">CURRENT ERA</div><h2>${level}</h2><p>${state.aura} aura points · ${state.streak}-day streak</p><div class="progress" style="margin-top:15px"><i style="width:${Math.min(100,state.aura/1500*100)}%"></i></div></div><div class="reward-star">✦</div></div><div class="grid stats-grid">${stat('Aura earned',state.aura+' ✦','From showing up')}${stat('Unlocked',defs.filter(x=>x[3]).length+'/'+defs.length,'Badges in your shelf')}${stat('Active quests',state.activeChallenges.length,'Keep it realistic')}${stat('Goals started',state.goals.length,'Future-you says thanks')}</div><section class="scratch-card panel"><div><div class="eyebrow">DAILY LITTLE SURPRISE</div><h3>Scratch me ✦ it’s giving lottery</h3><p class="muted">A tiny daily reward for showing up. Just for fun; no real money involved.</p><div id="scratch-result" class="scratch-result">${state.scratchDate===new Date().toDateString()?'You found +'+(state.scratchReward||0)+' aura yesterday/today ✨':'Your tiny surprise is waiting.'}</div></div>${state.scratchDate===new Date().toDateString()?btn('Come back tomorrow','scratch-reward','outline','disabled'):btn('Reveal my surprise ✨','scratch-reward','primary')}</section><section class="panel"><div class="panel-head"><h3>Achievements</h3><span class="pill">UNLOCK AS YOU GO</span></div><div class="badge-grid">${defs.map(x=>`<div class="badge-card ${x[3]?'earned':'locked'}"><div class="badge-icon">${x[3]?x[4]:'🔒'}</div><b>${x[1]}</b><small>${x[2]}</small><span class="pill ${x[3]?'green':''}">${x[3]?'Unlocked':'Not yet'}</span></div>`).join('')}</div></section><section class="panel" style="margin-top:18px"><h3>How aura works</h3><p class="muted" style="margin-top:8px">Aura celebrates logging, planning, and thoughtful decisions. It is a playful progress mechanic—not a measure of your worth or financial success.</p></section>`}
function board(){state.board=state.board||[];let starters=[{id:Date.now(),text:'Small choices today, a freer tomorrow. ♡',kind:'note',font:'hand',sticker:'✿',x:4,y:7},{id:Date.now()+1,text:'JAIPUR WEEKEND',kind:'goal',font:'serif',sticker:'🎯',x:37,y:18}];return `${head('MAKE THE FUTURE FEEL REAL','Your vision board. ✿','Pin notes, badges, stickers and goals. Drag them around, double-click text to edit, and build a board that feels like your future.',btn('＋ Add a note','board-note','primary')+btn('＋ Add a goal','board-goal','outline')+btn('Clear board','board-clear','outline')+btn('Reset board','board-reset','outline'))}<div class="board-intro"><span class="hand">little by little, a life I love ♡</span><p>Drag notes to rearrange your board. Double-click text to edit. It saves in this browser.</p></div><div class="vision-canvas" id="vision-canvas">${state.board.map((x,i)=>{let xx=Number.isFinite(x.x)?x.x:5+(i%3)*30,yy=Number.isFinite(x.y)?x.y:8+Math.floor(i/3)*36;return `<article class="vision-note v${i%5}" data-board-id="${x.id}" data-font="${x.font||'hand'}" style="left:${xx}%;top:${yy}%;--note-scale:${x.size||1};transform:rotate(${Number.isFinite(x.rot)?x.rot:(i%3===0?-1:i%3===1?1.3:-.3)}deg)" draggable="true" title="Drag to move · double-click text to edit"><button class="vision-delete" data-act="board-delete" data-id="${x.id}" aria-label="Delete note">×</button><span class="vision-sticker">${esc(x.sticker||(x.kind==='goal'?'🎯':x.kind==='quote'?'♡':'✳'))}</span><p data-edit-note="${x.id}">${esc(x.text)}</p>${x.kind==='goal'?'<small>A future worth saving for.</small>':''}<div class="vision-actions"><button class="choice" data-act="board-size" data-dir="down" data-id="${x.id}" aria-label="Smaller text">A−</button><button class="choice" data-act="board-size" data-dir="up" data-id="${x.id}" aria-label="Larger text">A+</button><button class="choice" data-act="board-rotate" data-dir="left" data-id="${x.id}" aria-label="Rotate left">↶</button><button class="choice" data-act="board-rotate" data-dir="right" data-id="${x.id}" aria-label="Rotate right">↷</button><button class="choice" data-act="board-edit" data-id="${x.id}">Edit</button><button class="choice" data-act="board-duplicate" data-id="${x.id}">Duplicate</button></div></article>`}).join('')}<button class="vision-add" data-act="board-note"><span>＋</span><b>Add a note</b><small>A goal, a reminder, a little dream.</small></button></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>Goals already in motion</h3>${btn('Open goals ↗','page-goals','outline')}</div>${state.goals.map(g=>`<div class="commit-row"><div class="ci">${g.emoji||'🎯'}</div><div class="grow"><b>${esc(g.name)}</b><small>${money(g.saved)} of ${money(g.target)} saved</small></div><div style="width:100px"><div class="progress"><i style="width:${Math.min(100,g.saved/Math.max(1,g.target)*100)}%"></i></div></div></div>`).join('')}</section>`}
function settings(){return `${head('YOUR SPACE, YOUR RULES','Settings & account.','Make the app feel like yours. Your demo data stays in this browser.') }<div class="grid two-col"><section class="panel"><div class="panel-head"><h3>Account basics</h3><span class="pill">LOCAL PROFILE</span></div><div class="form-grid"><div class="form-field"><label>Display name</label><input id="set-name" value="${esc(state.name)}"></div><div class="form-field"><label>Email</label><input value="${esc(state.email)}" disabled></div></div>${btn('Save profile','save-profile','primary')}<div class="toggle-row"><div><b>Dark mode</b><small>For late-night money lore.</small></div><button class="switch ${state.theme==='dark'?'on':''}" data-act="toggle-theme" aria-label="Toggle dark mode"><i></i></button></div><div class="toggle-row"><div><b>Unhinged copy</b><small>Memes and slang, with the maths intact.</small></div><button class="switch ${state.mode==='chill'?'on':''}" data-act="toggle-vibe" aria-label="Toggle copy mode"><i></i></button></div><div class="toggle-row"><div><b>Chaos events</b><small>Unexpected expense scenarios in the simulator.</small></div><button class="switch ${state.chaos?'on':''}" data-act="toggle-chaos" aria-label="Toggle chaos events"><i></i></button></div><div class="toggle-row"><div><b>Quiet mode</b><small>Keep the money nudges calm and minimal.</small></div><button class="switch ${state.quiet?'on':''}" data-act="toggle-quiet" aria-label="Toggle quiet mode"><i></i></button></div></section><div class="grid"><section class="panel"><div class="panel-head"><h3>Data & privacy</h3><span class="pill pink">READ THIS</span></div><p class="muted" style="font-size:12px;line-height:1.8">This is a front-end prototype. Data is stored in localStorage on this device. There is no real server, encrypted database, email verification, password reset, or cross-device sync. Do not enter real sensitive financial data.</p><div class="modal-actions">${btn('Export my data ↓','export-data','outline')}${btn('Reset demo data','reset-data','outline')}</div></section><section class="panel"><div class="panel-head"><h3>Danger zone</h3></div><p class="muted" style="font-size:12px;margin-bottom:14px">Log out of this local session. Your saved local profile will remain on this browser.</p>${btn('Log out','logout','outline')}</section></div></div>`}
function render(){if(!state)return;let html=({home,tracker,simulate,plan,goals,commitments,challenges:challengesPage,insights,settings,decide,tea,health,rewards,board})[currentPage]?.()||home();if(currentPage==='tea'&&!state.seenTea){state.seenTea=true;persist()}if(currentPage==='decide'&&!state.seenDecide){state.seenDecide=true;persist()}$('#page-content').innerHTML=html;$('#page-crumb').textContent=({home:'OVERVIEW',tracker:'TRACK MONEY',simulate:'WHAT-IF LAB',plan:'MONTH PLAN',goals:'GOALS',commitments:'BILLS & SUBS',challenges:'CHALLENGES',insights:'MONEY LORE',settings:'SETTINGS',decide:'SHOULD I BUY THIS?',tea:'CHAI PE CHARCHA',health:'FINANCIAL HEALTH',rewards:'BADGES & AURA',board:'VISION BOARD'})[currentPage]||'OVERVIEW';$('#side-name').textContent=state.name;$('#side-avatar').textContent=(state.name[0]||'M').toUpperCase();$('#profile-btn').textContent=(state.name[0]||'M').toUpperCase();if(currentPage==='simulate')wireSim();if(currentPage==='decide')evaluateDecision();if(currentPage==='board')wireBoard();if(currentPage==='tracker')$('#tx-search')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase();$('#tx-results').innerHTML=txList(state.tx.filter(t=>(t.note+' '+(CATS[t.cat]||['',''])[1]).toLowerCase().includes(q)))})}
function wireSim(){['sim-amt','sim-kind','sim-shock'].forEach(id=>$('#'+id)?.addEventListener('input',updateSim));updateSim()}
function updateSim(){if(!$('#sim-amt'))return;let amt=Math.max(0,Number($('#sim-amt').value)||0),shock=Number($('#sim-shock').value)||0,kind=$('#sim-kind').value,after=balance()-amt-shock,forecast=after-Math.max(0,daily())*Math.max(0,daysLeft()-1);$('#shock-val').textContent=money(shock);$('#sim-balance').textContent=money(after);$('#sim-progress').style.width=Math.max(0,Math.min(100,after/Math.max(1,state.budget)*100))+'%';let msg=kind==='need'?'If it is essential, make room for it and adjust another category.':after<0?'Hard pass for now. This takes your logged balance below zero.':forecast<0?'Maybe wait. This purchase makes the rest of the month fragile.':'Looks doable, if you still want it after a 24-hour pause.';$('#sim-verdict').innerHTML=`<div class="eyebrow">MABEL’S TAKE</div><h3>${msg}</h3><p>Estimated balance after the purchase: ${money(after)}. Simple end-of-month estimate: ${money(forecast)}.</p>`;let mc=runMonteCarlo(amt,shock);if($('#mc-survival'))$('#mc-survival').textContent=mc.survival+'%';if($('#mc-low'))$('#mc-low').textContent=money(mc.low);if($('#mc-mid'))$('#mc-mid').textContent=money(mc.mid);if($('#mc-high'))$('#mc-high').textContent=money(mc.high)}
function evaluateDecision(){let amt=Math.max(0,Number($('#decide-amt')?.value)||0),kind=$('#decide-kind')?.value||'want',age=Number($('#decide-age-value')?.value)||0,after=balance()-amt,projected=after-Math.max(0,daily())*Math.max(0,daysLeft()-1),leftDays=Math.max(1,daysLeft()),newDaily=Math.max(0,(after-state.subs.filter(s=>s.active&&s.due>state.day).reduce((a,s)=>a+s.amt,0)-state.bills.filter(s=>s.active&&s.due>state.day).reduce((a,s)=>a+s.amt,0))/leftDays),fundHit=state.goals.length?Math.min(amt,state.goals.reduce((a,g)=>a+Math.max(0,g.target-g.saved),0)):0;let verdict=kind==='need'?(after<0?'It is a real need, but the current plan cannot absorb it comfortably. Check whether another cost can move.':'If it is essential, make room for it and adjust the rest of the month.'):(after<0?'Hard pass for now. This would take your logged balance below zero.':projected<0?'Wait a little. This purchase makes the rest of the month fragile.':age<7?'Add it to the wishlist and give it a week. If you still want it, check the plan again.':'You have waited a bit. If the goal still matters and the numbers work, it may fit.');let el=$('#decide-result');if(el)el.innerHTML=`<div class="eyebrow">MABEL’S TAKE</div><h3>${esc(verdict)}</h3><div class="budget-row"><span>Balance after buying</span><b>${money(after)}</b></div><div class="budget-row"><span>New daily guide</span><b>${money(newDaily)}</b></div><div class="budget-row"><span>Potential goal trade-off</span><b>${money(fundHit)}</b></div><p>Estimated month-end after this choice: ${money(projected)}. This is a simplified estimate from your logged data.</p><div class="modal-actions"><button class="btn outline" data-act="decide-wait">Wait a week</button><button class="btn primary" data-act="decide-save">Save to wishlist</button></div>`;return {amt,kind,age,projected,after}}
function saveDecision(wait){let name=$('#decide-name')?.value.trim()||'Wishlist item',r=evaluateDecision(),age=Number($('#decide-age-value')?.value)||0,existing=state.wishlist.find(w=>w.name.toLowerCase()===name.toLowerCase());if(existing){existing.amt=r.amt;existing.age=wait?Math.max(7,age):age}else state.wishlist.push({id:Date.now(),name,amt:r.amt,age:wait?Math.max(7,age):age});persist();render();toast(wait?'Saved for a 7-day rethink. Future-you gets a vote.':'Saved to your wishlist. No pressure to buy.');}
let boardDragId=null;function wireBoard(){let canvas=$('#vision-canvas');if(!canvas)return;canvas.addEventListener('dragstart',e=>{let card=e.target.closest('[data-board-id]');if(!card)return;boardDragId=card.dataset.boardId;card.classList.add('dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',boardDragId)}});canvas.addEventListener('dragend',e=>{let card=e.target.closest('[data-board-id]');if(card)card.classList.remove('dragging')});canvas.addEventListener('dragover',e=>{if(boardDragId)e.preventDefault()});canvas.addEventListener('drop',e=>{if(!boardDragId)return;e.preventDefault();let card=state.board.find(x=>String(x.id)===String(boardDragId));if(!card)return;let r=canvas.getBoundingClientRect(),cw=Math.max(1,r.width),ch=Math.max(1,r.height);card.x=Math.max(0,Math.min(76,(e.clientX-r.left)/cw*100-10));card.y=Math.max(0,Math.min(76,(e.clientY-r.top)/ch*100-10));boardDragId=null;persist();render()});canvas.addEventListener('dblclick',e=>{let p=e.target.closest('[data-edit-note]');if(!p)return;let n=state.board.find(x=>String(x.id)===String(p.dataset.editNote));if(n)openBoardModal(n)})}
function openBoardModal(note){let n=note||{},isEdit=!!n.id;openModal(isEdit?'Edit your board note':'Add to your vision board',`<div class="form-field"><label>What do you want to remember?</label><textarea id="board-text" maxlength="180" placeholder="A trip I am saving for, a reminder, a little dream…">${esc(n.text||'')}</textarea></div><div class="form-grid"><div class="form-field"><label>Pin style</label><select id="board-kind"><option value="note" ${n.kind==='note'?'selected':''}>Handwritten note</option><option value="goal" ${n.kind==='goal'?'selected':''}>Goal card</option><option value="quote" ${n.kind==='quote'?'selected':''}>Quote / affirmation</option></select></div><div class="form-field"><label>Typography</label><select id="board-font"><option value="hand" ${(!n.font||n.font==='hand')?'selected':''}>Handwritten</option><option value="serif" ${n.font==='serif'?'selected':''}>Editorial serif</option><option value="marker" ${n.font==='marker'?'selected':''}>Marker / chill</option></select></div><div class="form-field full-span"><label>Sticker</label><select id="board-sticker">${['✿','♡','✦','🎯','🌷','🪩','🦋','🍓','🌙','⭐','💸','🛟','🏆','🧠','🎖️','✨'].map(x=>`<option ${n.sticker===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`,'Pin to board','save-board-note');$('#modal-root').dataset.boardEdit=isEdit?n.id:''}
function openModal(title,body,submitLabel,submitAct){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="close" data-act="close-modal" aria-label="Close">×</button></div>${body}<div class="modal-actions"><button class="btn outline" data-act="close-modal">Cancel</button><button class="btn primary" data-act="${submitAct}">${submitLabel}</button></div></div></div>`}
function txModal(type='out'){openModal(type==='in'?'Money came in 💸':'Log a transaction ✳',`<form id="tx-form" class="form-grid"><div class="form-field full-span"><label>Type</label><select id="f-type"><option value="out" ${type==='out'?'selected':''}>Expense / money out</option><option value="in" ${type==='in'?'selected':''}>Income / money in</option></select></div><div class="form-field"><label>Amount (₹)</label><input id="f-amt" type="number" min="1" max="10000000" required placeholder="290"></div><div class="form-field"><label>Category</label><select id="f-cat">${Object.keys(CATS).filter(k=>type==='in'?k==='income':!['income','goal'].includes(k)).map(k=>`<option value="${k}">${CATS[k][0]} ${CATS[k][1]}</option>`).join('')}</select></div><div class="form-field full-span"><label>What was it?</label><input id="f-note" maxlength="80" placeholder="Chai, metro, freelance…"></div><div class="form-field"><label>Day</label><input id="f-day" type="number" min="1" max="${state.days}" value="${state.day}"></div><div class="form-field"><label>Paid with</label><select id="f-pay"><option>UPI</option><option>Cash</option><option>Card</option><option>Bank</option></select></div></form>`,'Save transaction','save-tx')}
function addTx(){let amt=Number($('#f-amt')?.value);if(!amt||amt<1){toast('Add an amount above ₹0 first.');return}let type=$('#f-type').value,cat=type==='in'?'income':$('#f-cat').value;state.tx.push({id:Date.now(),day:Math.min(state.days,Math.max(1,Number($('#f-day').value)||state.day)),type,amt,cat,note:$('#f-note').value.trim()||CATS[cat][1],pay:$('#f-pay').value.toLowerCase()});if(type==='out'){state.aura+=5;state.streak=Math.max(1,state.streak)}persist();$('#modal-root').innerHTML='';render();toast(type==='in'?'Money in. We love a plot twist. +5 aura ✦':'Logged. Awareness is the whole point. +5 aura ✦')}
function newGoal(){openModal('New money goal ◎',`<form id="goal-form" class="form-grid"><div class="form-field full-span"><label>Goal name</label><input id="g-name" required maxlength="50" placeholder="Weekend trip, emergency fund…"></div><div class="form-field"><label>Target amount (₹)</label><input id="g-target" type="number" min="1" required placeholder="5000"></div><div class="form-field"><label>Emoji</label><select id="g-emoji"><option>🎯</option><option>🛟</option><option>🚆</option><option>🎧</option><option>💻</option><option>🪩</option></select></div></form>`,'Create goal','save-goal')}
function newCommit(){openModal('Add a recurring cost ⟳',`<form class="form-grid"><div class="form-field full-span"><label>Name</label><input id="c-name" required placeholder="Spotify, Wi-Fi, bus pass…"></div><div class="form-field"><label>Amount (₹)</label><input id="c-amt" type="number" min="1" required placeholder="199"></div><div class="form-field"><label>Type</label><select id="c-type"><option value="sub">Subscription</option><option value="bill">Bill / essential</option></select></div><div class="form-field"><label>Due day</label><input id="c-due" type="number" min="1" max="${state.days}" value="15"></div><div class="form-field"><label>Emoji</label><input id="c-emoji" value="🧾" maxlength="4"></div></form>`,'Add commitment','save-commit')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(!b)return;let a=b.dataset.act,id=b.dataset.id;
switch(a){
case'open-tx':txModal('out');break;case'open-income':txModal('in');break;case'close-modal':if(e.target.classList.contains('modal-backdrop')||e.target.closest('.close')||e.target.closest('[data-act="close-modal"]'))$('#modal-root').innerHTML='';break;case'save-tx':addTx();break;
case'delete-tx':state.tx=state.tx.filter(t=>String(t.id)!==String(id));persist();render();toast('Entry removed.');break;
case'quick-chai':state.tx.push({id:Date.now(),day:state.day,type:'out',amt:40,cat:'food',note:'Chai',pay:'upi'});state.aura+=5;persist();render();toast('Chai logged. Main character hydration ☕');break;
case'page-sim':go('simulate');break;case'page-plan':go('plan');break;case'page-goals':go('goals');break;case'page-challenges':go('challenges');break;case'page-commitments':go('commitments');break;case'page-tea':go('tea');break;case'page-health':go('health');break;case'page-decide':go('decide');break;case'page-board':go('board');break;case'page-rewards':go('rewards');break;
case'decide-age':$('#decide-age-value').value=b.dataset.age;$$(['[data-act="decide-age"]']).forEach(x=>x.classList.toggle('selected',x===b));break;case'decide-run':evaluateDecision();break;case'decide-save':saveDecision(false);break;case'decide-wait':saveDecision(true);break;case'decide-buy':{let w=state.wishlist.find(x=>String(x.id)===String(id));if(w){$('#decide-name').value=w.name;$('#decide-amt').value=w.amt;$('#decide-age-value').value=w.age||0;evaluateDecision();}break;}
case'choose-vibe':{let mode=b.dataset.mode;if(mode!=='aesthetic'&&mode!=='chill')break;localStorage.setItem('mabel-preferred-mode',mode);document.documentElement.dataset.mode=mode;$$('[data-act=choose-vibe]').forEach(x=>x.classList.toggle('selected',x===b));toast(mode==='chill'?'Chill mode selected 😎':'Aesthetic mode selected ✿');if(state){state.mode=mode;persist();render()}break;}case'board-clear':if(confirm('Clear every note from this vision board?')){state.board=[];persist();render();toast('Board cleared. Start a new chapter.')}break;case'board-reset':if(confirm('Reset the board to Mabel’s starter notes?')){state.board=[{id:Date.now(),text:'Small choices today, a freer tomorrow. ♡',kind:'note',font:'hand',sticker:'✿',x:4,y:7},{id:Date.now()+1,text:'JAIPUR WEEKEND',kind:'goal',font:'serif',sticker:'🎯',x:37,y:18}];persist();render();toast('Starter board restored.')}break;case'board-duplicate':{let n=state.board.find(x=>String(x.id)===String(id));if(n){state.board.push({...n,id:Date.now(),text:n.text+' (copy)',x:Math.min(70,(n.x||5)+8),y:Math.min(70,(n.y||5)+8)});persist();render();toast('Note duplicated. Make it yours.')}break;}case'board-size':{let n=state.board.find(x=>String(x.id)===String(id));if(n){n.size=Math.max(.75,Math.min(1.6,(n.size||1)+(b.dataset.dir==='up'?.1:-.1)));persist();render()}break;}case'board-rotate':{let n=state.board.find(x=>String(x.id)===String(id));if(n){n.rot=(Number.isFinite(n.rot)?n.rot:0)+(b.dataset.dir==='right'?5:-5);if(n.rot>15)n.rot=-15;if(n.rot< -15)n.rot=15;persist();render()}break;}case'board-note':openBoardModal();break;case'board-goal':go('goals');break;case'board-edit':{let n=state.board.find(x=>String(x.id)===String(id));if(n)openBoardModal(n);break;}case'board-delete':state.board=state.board.filter(x=>String(x.id)!==String(id));persist();render();toast('Note removed from your board.');break;case'save-board-note':{let text=$('#board-text')?.value.trim(),kind=$('#board-kind')?.value||'note',font=$('#board-font')?.value||'hand',sticker=$('#board-sticker')?.value||'✿',edit=$('#modal-root').dataset.boardEdit;if(!text){toast('Give your note a little something.');break}if(edit){let n=state.board.find(x=>String(x.id)===String(edit));if(n){n.text=text;n.kind=kind;n.font=font;n.sticker=sticker}}else state.board.push({id:Date.now(),text,kind,font,sticker,x:Math.max(3,(state.board.length%3)*31+3),y:Math.min(70,Math.floor(state.board.length/3)*34+5)});persist();$('#modal-root').innerHTML='';go('board');toast('Pinned to your vision board ✿');break;}
case'run-sim':updateSim();toast('Scenario recalculated. No real money moved.');break;case'rerun-monte':updateSim();toast('300 possible months simulated again.');break;case'apply-shock':$('#sim-shock').value=Number($('#sim-shock').value||0)+Number(b.dataset.amt);updateSim();toast('Plot twist added to your scenario.');break;
case'save-plan':{let bud=Number($('#plan-budget')?.value),days=Number($('#plan-days')?.value),day=Number($('#plan-day')?.value);if(!bud||bud<1){toast('Budget must be above zero.');break}state.budget=bud;state.days=days;state.day=Math.min(days,Math.max(1,day||1));let mainQuest=challenges.find(x=>x.id==='main');if(state.day>=mainQuest.days&&balance()>=0&&!state.doneChallenges.includes('main')){state.doneChallenges.push('main');state.activeChallenges=state.activeChallenges.filter(x=>x!=='main');state.aura+=mainQuest.reward;}persist();render();toast(state.doneChallenges.includes('main')?'Main quest cleared. +150 aura ✨':'Month recalculated ✳');break}
case'new-goal':newGoal();break;case'save-goal':{let name=$('#g-name')?.value.trim(),target=Number($('#g-target')?.value);if(!name||!target||target<1){toast('Add a goal name and target.');break}state.goals.push({id:Date.now(),name,target,saved:0,emoji:$('#g-emoji').value});persist();$('#modal-root').innerHTML='';go('goals');toast('Goal created. Future you says thanks.');break}
case'fund-goal':{let g=state.goals.find(g=>String(g.id)===String(id));if(!g)break;openModal('Fund '+esc(g.name)+' ◎',`<p class="muted" style="font-size:12px;margin-bottom:14px">Saved ${money(g.saved)} of ${money(g.target)}. Contributions are recorded as goal allocations in this prototype; ensure the money is actually set aside in real life.</p><div class="form-field"><label>Contribution (₹)</label><input id="fund-amt" type="number" min="1" max="${Math.max(1,g.target-g.saved)}" placeholder="500"></div>`,'Add to goal','save-fund');$('#modal-root').dataset.goal=id;break}
case'save-fund':{let g=state.goals.find(g=>String(g.id)===$('#modal-root').dataset.goal),amt=Number($('#fund-amt')?.value);if(!g||!amt||amt<1){toast('Enter a contribution amount.');break}amt=Math.min(amt,g.target-g.saved);g.saved+=amt;state.tx.push({id:Date.now(),day:state.day,type:'out',amt,cat:'goal',note:'Goal: '+g.name,pay:'allocation'});state.aura+=10;persist();$('#modal-root').innerHTML='';render();toast('Goal funded a little more. +10 aura ✦');break}
case'new-commit':newCommit();break;case'save-commit':{let name=$('#c-name')?.value.trim(),amt=Number($('#c-amt')?.value),type=$('#c-type')?.value,due=Number($('#c-due')?.value);if(!name||!amt||amt<1){toast('Add a name and amount.');break}let item={id:Date.now(),name,amt,due:Math.min(state.days,Math.max(1,due||1)),emoji:$('#c-emoji').value||'🧾',active:true};(type==='sub'?state.subs:state.bills).push(item);persist();$('#modal-root').innerHTML='';render();toast('Commitment added. Future-you is informed.');break}
case'toggle-commit':{let list=b.dataset.type==='sub'?state.subs:state.bills,item=list.find(x=>String(x.id)===String(id));if(item)item.active=!item.active;persist();render();toast(item?.active?'Commitment resumed.':'Commitment paused.');break}
case'review-sub':{let sub=state.subs.find(x=>String(x.id)===String(id));if(sub){sub.reviewed=true;persist();render();toast('Subscription reviewed. Keep or pause it with intention.')}break;}case'scratch-reward':{let today=new Date().toDateString();if(state.scratchDate===today){toast('Your daily surprise is already claimed.');break}let prize=[25,50,75,100][Math.floor(Math.random()*4)];state.scratchDate=today;state.scratchReward=prize;state.aura+=prize;persist();render();toast('You found +'+prize+' aura! Tiny win unlocked ✨');break;}case'challenge-tick':{let ch=challenges.find(x=>x.id===id);if(!ch||!state.activeChallenges.includes(id))break;let todayTx=state.tx.filter(t=>t.day===state.day&&t.type==='out');let okay=true,why='';if(id==='delivery'&&todayTx.some(t=>t.cat==='delivery')){okay=false;why='Food delivery showed up in today’s log. Try again on a delivery-free day.'}if(id==='cash'&&todayTx.some(t=>t.pay!=='cash')){okay=false;why='Today has a non-cash expense logged. Cash-only means every purchase today is cash.'}if(id==='wait'&&!state.wishlist.some(w=>(w.age||0)>=7)){okay=false;why='Save a want to your wishlist and give it a full week first.'}if(id==='under'&&spentDay(state.day)>state.budget/Math.max(1,state.days)){okay=false;why='Today’s spending is above the simple daily budget guide.'}if(id==='weekend'&&todayTx.some(t=>['delivery','shopping','fun'].includes(t.cat))){okay=false;why='A wants-category spend is logged today. Try a needs-only day.'}if(id==='purge'&&!state.subs.every(x=>x.reviewed||x.active===false)){okay=false;why='Review or pause every subscription first, then count the win.'}if(!okay){toast(why);break;}state.challengeProgress[id]=(state.challengeProgress[id]||0)+1;if(state.challengeProgress[id]>=ch.days){state.challengeProgress[id]=ch.days;state.activeChallenges=state.activeChallenges.filter(x=>x!==id);if(!state.doneChallenges.includes(id))state.doneChallenges.push(id);state.aura+=ch.reward;state.streak=Math.max(state.streak,1);persist();render();toast(ch.name+' cleared! +'+ch.reward+' aura ✨')}else{persist();render();toast('Today counts. '+state.challengeProgress[id]+'/'+ch.days+' days done.')}break;}case'join-challenge':if(!state.activeChallenges.includes(id))state.activeChallenges.push(id);state.challengeProgress[id]=state.challengeProgress[id]||0;persist();render();toast('Quest accepted. Tiny wins, big lore.');break;
case'leave-challenge':state.activeChallenges=state.activeChallenges.filter(x=>x!==id);persist();render();toast('Quest paused. You can pick it up again.');break;
case'save-profile':{let n=$('#set-name')?.value.trim();if(n&&n.length>1){state.name=n;persist();render();toast('Profile updated.');}else toast('Name needs at least two characters.');break}
case'toggle-theme':state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;persist();render();break;
case'toggle-vibe':state.mode=state.mode==='chill'?'aesthetic':'chill';document.documentElement.dataset.mode=state.mode;persist();render();toast(state.mode==='chill'?'Chill mode: memes, neon and no judgement.':'Aesthetic mode: soft editorial Mabel.');break;
case'toggle-chaos':state.chaos=!state.chaos;persist();render();toast('Chaos events '+(state.chaos?'on':'off')+'.');break;case'toggle-quiet':state.quiet=!state.quiet;persist();render();toast(state.quiet?'Quiet mode on. Less noise, same clarity.':'Quiet mode off. Mabel can talk again.');break;
case'export-data':{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mabel-data.json';a.click();URL.revokeObjectURL(url);toast('Your data export is ready.');break}
case'reset-data':if(confirm('Reset the demo data for this local account? This cannot be undone.')){let email=state.email,name=state.name;state=defaults();state.email=email;state.name=name;persist();render();toast('Fresh start. New chapter.');}break;
case'logout':logout();break;
}
});
$('#page-content').addEventListener('submit',e=>e.preventDefault());
$('#page-content').addEventListener('input',e=>{if(e.target.id==='sim-amt'||e.target.id==='sim-shock'||e.target.id==='sim-kind')updateSim();if(['decide-amt','decide-kind','decide-name','decide-age-value'].includes(e.target.id))evaluateDecision()});
function checkSession(){let email=localStorage.getItem('mabel-session');if(email){state=loadSaved(email);if(state){startApp();return}}authView('login')}
checkSession();
})();